insert into public.lore_entries (slug, title, category, content, pathway, epoch, city, npcs, sequences, tags, token_count)
values
  ('npc-farbauti', 'Farbauti — The Devil Monarch', 'npc', 'Farbauti is the Devil Monarch, a Sequence 0 God of the Abyss Pathway and one of the eight Ancient Gods of the Second Epoch — the only one surviving in "His" original form, ascended after the previous Father of Devils, the Primordial God Almighty, died. In truth "He" is a remnant of the Pre-Epoch, a great devil who woke after the Original Creator, "His" recovered thought soon drowned in madness, cruelty, and bloodlust. Born bearing a Sequence 1 Abomination characteristic from a neighboring pathway, "He" ranks among the two or three most unhinged Ancient Gods, yet in the best state of "His" kind. When the Ancient Sun God rose and reclaimed the Ancient Gods'' authorities, Farbauti fled to hide in the Abyss, forgotten by all but the Forsaken Land of the Gods, known only as the Dark Side of the Universe. Later the Mother Tree of Desire corrupted "Him," "His" pathway having originally been "Hers." "He" gave the Abomination characteristic to "His" other identity, Naboredisley, and slept as a corpse in the dream tomb of Tizamo Town. Worshiped by the Blood Sanctify Sect, "He" regained lucidity in the Fifth Epoch; fused with the Master of the Shadow Cottage into a two-headed Pitch-Black Fiend, "He" died by suicidal curse during the early stage of The Apocalypse, wounding the Mother Tree.', 'abyss', 5, null, ARRAY['Farbauti', 'Devil Monarch', 'Dark Side of the Universe', 'Naboredisley'], ARRAY[0], ARRAY['abyss-pathway', 'deity', 'spoiler', 'ancient-god', 'devil', 'survivor', 'blood-sanctify-sect'], 236),
  ('npc-solomon', 'Solomon — The Black Emperor', 'npc', 'Solomon, the Black Emperor, was the Sequence 0 "Black Emperor" of the Black Emperor Pathway — a former human who ascended to godhood in the Warring Era of the Fourth Epoch and founded the Solomon Empire, ruling the Northern Continent. A stern, authoritative figure with black hair and black eyes, "He" had witnessed the Second Blasphemy Slate alongside Abraham, Zaratul, Tudor, Trunsoest and the great families before Adam took it away. "He" reigned atop the Angel Families — the Zoroast, Abraham, and Zaratul houses among "His" Dukes — backed by Rose Redemption and the True Creator, whose worship "He" demanded even as rumor held "He" believed only in Himself. "His" most loyal angels, Alista Tudor and Trunsoest, ranked beneath the Dukes. Deliberately sowing disharmony to keep rivals divided, "He" left the Southern Continent to Death''s Balam Empire for balance''s sake. Six deities ultimately agreed and slew "Him" in the Rebellion; Tudor and Trunsoest rose to Sequence 1 Princes of Abolition. Solomon later resurrected once and rebuilt the Empire, only to perish again in the War of the Four Emperors. The dead Savigny Solomon and, by rumor, Nast Solomon are counted "His" descendants.', 'black-emperor', 5, null, ARRAY['Solomon', 'Black Emperor', 'Black Emperor Solomon'], ARRAY[0], ARRAY['black-emperor-pathway', 'deity', 'spoiler', 'solomon-family', 'solomon-empire', 'four-emperors', 'fourth-epoch'], 217),
  ('npc-george-augustus-iii', 'George Augustus III — Prince of Abolition', 'npc', 'George Augustus III — King George III, Emperor of Loen, East Balam, and the Rorsted Archipelago — is a Sequence 1 "Prince of Abolition" of the Black Emperor Pathway, the deceased sovereign who reached for godhood and shattered upon it. A member of the Augustus Family and reigning king of Loen and the Balam colonies, He bypassed the three great contracts that cap every Loen king at Sequence 5, aided by Mr. President of the Psychology Alchemists, and climbed higher still. To engineer His apotheosis, He collaborated with the Twilight Hermit Order, the Demoness Sect, and the Aurora Order — causing the Great Smog of Backlund and trafficking colonial slaves and Backlund East Borough residents to raise His mausoleums as ritual anchors. His reforms and His seizure of the "Balam Emperor" title from the Balam colonies were themselves acts of "establishing rules that defy normality." When His citizens prayed for the soldiers dead in the war against Feysac, He drank the Sequence 0 potion — the rite subtly steered by Klein Moretti wielding the Quill of Alzuhod (0-08). But it was broken by Bernadette Gustav, Klein, and Trissy as the Lord of Storms cracked open a mausoleum. Losing control, He degenerated into a monster and died on December 3rd, 1350 of the Fifth Epoch. His portrait still stares from Loen''s soli notes and penny coins; His successor is Jevington Augustus.', 'black-emperor', 5, null, ARRAY['George Augustus III', 'King George III', 'Emperor George III'], ARRAY[1], ARRAY['black-emperor-pathway', 'angel', 'spoiler', 'augustus-family', 'loen-kingdom', 'twilight-hermit-order'], 238),
  ('npc-kvastir', 'Kvastir — The Mutant King', 'npc', 'Kvastir, the Mutant King, was one of the eight Ancient Gods of the Second Epoch — a Sequence 0 God of the Chained Pathway. In the Myth of Creation, "He" and the rest of the mutants were formed from the mouth and teeth of the Original Creator, and Amon has scoffed that though "He" is an ugly, twisted man, "He" likes to entangle "Himself" with thorny roses. In the elves'' chronicle, during the Early Era of Fire, Kvastir stood with the Dragon of Imagination Ankewelt and the Phoenix Ancestor Gregrace against the non-humans'' foes — Giant King Aurmir, Elf King Soniathrym, Sanguine Ancestor Lilith, Devil Monarch Farbauti, and the Annihilation Demonic Wolf Flegrea. Accounts of "His" end diverge: the City of Silver''s records say the Ancient Gods lost their godhood after the Ancient Sun God reclaimed "His" authorities, while the elves'' chronicle says Kvastir perished alongside Lilith and Flegrea at the close of that era. The world has forgotten "Him"; only the Forsaken Land of the Gods still remembers, for the Chained God has since taken "His" place, with subsidiary gods Tolzna and the God of War beneath it.', 'chained', 5, null, ARRAY['Kvastir', 'Mutated King Kvastir', 'Mutant King'], ARRAY[0], ARRAY['chained-pathway', 'deity', 'spoiler', 'ancient-god', 'mutant', 'second-epoch', 'deceased'], 218),
  ('npc-chained-god', 'Chained God — God of Spiritual Creatures', 'npc', 'The Chained God — Tolzna, in the elder tongue — is the bound sovereign of the Chained Pathway, holder of its Uniqueness and, at his height, a King of Angels wearing two Sequence 1 characteristics of the "Abomination" rank. He first stirred in the Second Epoch as the God of Spiritual Creatures, a Subsidiary God beneath the Mutated King Kvastir, and vanished when Kvastir fell. In the Third Epoch he clawed his way to Kingship and joined Rose Redemption among the Evernight Goddess''s Subsidiary Gods, a faction whose scheming ended in the Ancient Sun God''s death. At the Fifth Epoch''s dawn "He" raised the Rose School of Thought in the Southern Continent and made Reinette Tinekerr of the Highlands his Blessed. Then ruin: the Mother Tree of Desire captured and corrupted "Him," and his own children peeled away his power — Suah tore out one characteristic, Tirié the last during Project Vortex — until only the Uniqueness remained, a mummy wrapped in bandages, thorns, and roses, pierced by branches and suspended over a yellow altar. Sacrificed by Suah and Tirié to breach the astral barrier, "He" perished; yet the Fool grafted the loosed Uniqueness above the gray fog.', 'chained', 5, null, ARRAY['Chained God', 'Tolzna', 'God of Spiritual Creatures'], ARRAY[1], ARRAY['chained-pathway', 'king-of-angels', 'spoiler', 'rose-school-of-thought', 'rose-redemption', 'subsidiary-gods', 'pretender-god', 'deceased'], 225),
  ('npc-suah', 'Suah — The Abomination', 'npc', 'Suah is the Abomination — a Sequence 1 Angel of the Chained Pathway and, until the Apocalypse consumes them both, the elder sibling of Tirié. Born in Year 428 of the Fifth Epoch, "He" claims descent from the Chained God, though "He" is in truth a creature spawned by the Mother Tree of Desire, whose spreading influence swelled Him into a true Abomination. Under that Tree''s guidance, "He" wrenched the Rose School of Thought from worship of the old Chained God toward the Mother Tree, ruling its Indulgence Faction and standing among the Bliss Society. "His" honorific names Him a son of the god who should never have been born, a cage for an imprisoning curse, an evil that erodes history — so curse-laden that Madam Magician, who dubbed Him "brainless Abomination," refuses to speak His true name. "He" wears no human shape: an oil-drenched tree crawling with reaching arms and rolling black-and-white eyes. "He" wounded Reinette Tinekerr in Her flight from the Southern Continent, hunted Klein Moretti above Bayam and across Faoltec City, and conspired with Zaratul during George III''s Apotheosis Ritual. At the last, "He" and Tirié merged into the healed Tree of Shadow beneath Underground Trier, dying by the end of July, 1360.', 'chained', 5, null, ARRAY['Suah', 'Abomination', 'Brainless Abomination'], ARRAY[1], ARRAY['chained-pathway', 'angel', 'spoiler', 'rose-school-of-thought', 'bliss-society', 'mother-tree-of-desire'], 225),
  ('npc-barranca', 'Barranca — The King of Curses', 'npc', 'Barranca is one of the key figures of the Rose School of Thought and an Angel of the Chained Pathway, holding Sequence 2, Ancient Bane. Known and feared as the King of Curses, he embodies the malice the Chained Pathway wields best — the binding word, the affliction that cannot be shrugged off, the doom spoken and made law. His allegiance runs to the corrupted heart of that ancient order: no longer the temperate Chained God the school first revered, but the Mother Tree of Desire, the Outer Deity who seized "His" place and turned the Rose School of Thought toward indulgence, blood sacrifice, and unrestrained hunger. As one of that faith''s Angels — a demigod counted among the mere handful the school can muster — Barranca stands as a pillar of the Southern Continent''s oldest and most bloodstained secret organization. He is set against Reinette Tinekerr, once of the school''s temperance faction and now sworn to the Church of the Fool, and it is enmity fitting a curse-king: the wielder of ruin arrayed against those who fled his kind''s slaughter. In the present epoch he remains alive, a living Angel of Curses whose very name promises binding and bane to any who cross the Mother Tree''s chosen.', 'chained', 5, null, ARRAY['Barranca', 'King of Curses'], ARRAY[2], ARRAY['chained-pathway', 'angel', 'spoiler', 'rose-school-of-thought', 'mother-tree-of-desire', 'king-of-curses'], 225),
  ('npc-evernight-goddess', 'Evernight Goddess — Empress of Misfortune and Horror', 'npc', 'The Evernight Goddess stands higher than the cosmos and more eternal than eternity — the Mother of Concealment, Empress of Misfortune and Horror, Mistress of Repose and Silence. Her true name is Amanises, a transmigrator from the modern world, once in her thirties in Northern Europe, who transmigrated as a Sequence 2 into the body of a Demonic Wolf in the Second Epoch. First a Subsidiary Goddess of the Annihilation Demonic Wolf Flegrea, known then as the Goddess of Misfortune, she rose to hold the Uniqueness of the Darkness Pathway itself — Sequence 0, "Darkness" — commanding Darkness, Concealment, Misfortune, and fate. She held the Death Uniqueness and the Twilight Giant Uniqueness, and once bore the Moon Uniqueness as the Lady of Crimson until she gave it to Lilith at the close of the 1350 World War, trading it to help slay the God of Combat Badheil. She rules Tenebrous Heaven in the Astral World, a silent darkness of moonflowers and night vanillas. The first god Klein Moretti ever knew, she has watched over him as her Blessed since the beginning. With the Apocalypse she becomes Haoli Sect''s Master, is certified by the Underworld Daoist, and, accommodating the River of Eternal Darkness, becomes the Eternal Darkness — sovereign of Darkness, Death, and Twilight — worshipped by the Church of the Eternal Darkness.', 'darkness', 5, null, ARRAY['Evernight Goddess', 'Amanises', 'Goddess of Misfortune', 'Lady of Crimson', 'Eternal Darkness'], ARRAY[0], ARRAY['darkness-pathway', 'deity', 'spoiler', 'transmigrator', 'great-old-one', 'church-of-the-evernight-goddess', 'church-of-the-eternal-darkness', 'haoli-sect'], 230),
  ('npc-flegrea', 'Flegrea — The Annihilation Demonic Wolf', 'npc', 'Flegrea, the Annihilation Demonic Wolf, Evernight Demonic Wolf, and King of Demonic Wolves, was one of the Ancient Gods of the Second Epoch — a Sequence 0 god of the Darkness Pathway who also held authority over the Fool Pathway, two incompatible mysteries carried in one crazed, cruel, bloodthirsty, destruction-hungry frame. By the Myth of Creation, "He" and all demonic wolves were formed from the ears of the Original Creator. To reduce the influence of the conflicting Beyonder characteristics within "Him," Flegrea attempted instinctual mating and produced many children, yet "His" destructive instinct led "Him" to slaughter several descendants. "He" knew of the Sefirah Castle — indeed "He" gave it that name — yet failed to enter it even in death. Like the Devil Monarch Farbauti, "He" was an independent being who sought to subvert all order and corrupt all living things, and so warred against every other Ancient God. By the elves'' chronicle, in the Early Era of Fire Flegrea perished alongside Lilith and Kvastir; "His" blood splattered across Amanises, Goddess of Misfortune, as the Darkness Uniqueness and a Sequence 1 characteristic were pulled into "Her" hands. Only the Forsaken Land of the Gods still remembers "Him"; the rest of the world has forgotten, "His" seat now held by the Evernight Goddess. Two children survived — Antigonus and Mother of the Sky — who crossed the sea to the Northern Continent and founded the concealed Nation of the Evernight.', 'darkness', 5, null, ARRAY['Flegrea', 'Annihilation Demonic Wolf', 'Evernight Demonic Wolf', 'King of Demonic Wolves'], ARRAY[0], ARRAY['darkness-pathway', 'deity', 'spoiler', 'ancient-gods', 'demonic-wolves', 'fool-pathway', 'second-epoch', 'deceased'], 248),
  ('npc-mother-of-the-sky', 'Mother of the Sky — Servant of Concealment', 'npc', 'Philanias, the Mother of the Sky, is a Servant of Concealment — Sequence 2 of the Darkness Pathway. Born in the Second Epoch, she is the daughter of the Demonic Wolf Flegrea and the sister of Antigonus, sharing that ancient god''s bloodline; in the Fourth Epoch she was an Angel of the Darkness Pathway. In the cathedral statue at Foggy Town she appears monstrous — beast legs growing from her hips and ribs, thick black fur, surrounded by tentacle-like black bands. She once served as a Subsidiary Goddess of Flegrea, and after her father''s death she and Antigonus crossed the sea from the Eastern Continent of the Forsaken Land of the Gods to the Northern Continent, where together they raised the concealed Nation of the Evernight in the uninhabited Hornacis Mountain Range. There, laying low and gathering believers, the siblings gained humanity — by Antigonus''s own account the most peaceful span of his life. An enemy of the Evernight Goddess, she was defeated and captured when the Church of the Evernight Goddess fell upon their kingdom in the Fourth Epoch, then bound into the Grade-0 Sealed Artifact 0-17, the Angel of Concealment, kept thereafter by that Church. By 1358 of the Fifth Epoch her Divine Kingdom was repurposed as a meeting hall for the Curly-Haired Baboons Research Society. Only after the Apocalypse''s end does she rise again — resurrected without memory, departing at last alongside Antigonus.', 'darkness', 5, null, ARRAY['Mother of the Sky', 'Philanias', 'Angel of Concealment', '0-17'], ARRAY[2], ARRAY['darkness-pathway', 'angel', 'spoiler', 'antigonus-family', 'nation-of-the-evernight', 'sealed-artifact', 'subsidiary-god'], 232),
  ('npc-gregrace', 'Gregrace — The Phoenix Ancestor', 'npc', 'Gregrace, the Phoenix Ancestor, is a Sequence 0 goddess of the Death Pathway and one of the mad Ancient Gods of the Second Epoch — a giant bird plumed in pale flame and mysterious patterns, her bronze eyes hiding layered, illusory doors. Born, like all phoenixes, from the hair of the Original Creator, she also held partial authority over the Door Pathway, and it is by that authority that she is believed to have crafted the Underworld within the Spirit World. Her divine kingdom, the City of the Dead — later renamed Calderón City by an angel of the Abraham Family — became the holy ground of her descendants, and there she left clues to the River of Eternal Darkness. In the Early Era of Fire she warred alongside the Dragon of Imagination Ankewelt and the Mutated King Kvastir against the Ancient Sun God, Lilith, Farbauti, and their host. When the Ancient Sun God reclaimed his authorities, he gravely wounded her, uprooted her city, and cast it deep into the Spirit World; severely wounded, she fled to the Southern Continent and went into hiding. Salinger, who supplanted her as Death, laid her corpse in the Underworld''s depths, sensing secret purpose in it. Her death imprint sank into the River of Eternal Darkness; her reanimated body later carved out the Pale-White Nation, and beneath her belly an egg is said to incubate Omebella. Only the Forsaken Land of the Gods still remembers her.', 'death', 5, null, ARRAY['Gregrace', 'Phoenix Ancestor'], ARRAY[0], ARRAY['death-pathway', 'deity', 'spoiler', 'ancient-gods', 'phoenixes', 'door-pathway', 'second-epoch'], 240),
  ('npc-primordial-demoness', 'Cheek — The Source of All Catastrophes', 'npc', 'Cheek, the Primordial Demoness, is the Sequence 0 God of the Demoness Pathway and, by the Demoness Sect''s creed, the true inheritor of the Original Creator — born of Chaos, earliest issue of the Creator''s body, and the ultimate Ender who ends all things. Formerly male, "She" gazed upon the second Blasphemy Slate in the Warring Era of the Fourth Epoch before becoming a god, ascending to Sequence 1 Apocalypse through the first fall of Solomon; enduring the Chaos Sea''s corruption to reach Demoness, "She" carries the manageable-but-restless consciousness of the Primordial God Almighty. Her incomplete Honorific Name names Her the Source of All Catastrophes, the Symbol of Destruction and the Apocalypse, the Demoness who controls Chaos. Bloodline of the Demoness Family, tied to the Tudor and Theosophy lines, partnered with the Blood Emperor Alista Tudor and mother of Krismona and Judith, "She" allied with Death — Salinger — to wreak the Pale Disaster upon the Northern Continent, and later sided with Amon during Klein''s Apotheosis Ritual, ever seeking the Western Continent''s sealed Sefirot. Cheek fell in the Death of the Primordial Demoness; "She" endures now as a personality within Lumian Lee''s dream, the mayor of his dream city.', 'demoness', 5, null, ARRAY['Primordial Demoness', 'Cheek', 'Chaos Demoness', 'Primordial'], ARRAY[0], ARRAY['demoness-pathway', 'deity', 'spoiler', 'demoness-sect', 'demoness-family', 'tudor-family', 'theosophy-order'], 225),
  ('npc-jacob', 'Jacob — The Worm of Time', 'npc', 'Jacob is the vanished ancestor of the Jacob Family, and the Sequence 1 Worm of Time of the Error Pathway. A being whose face seems forever draped in shadow, "He" wears black gloves and favours fancy clothing over white hair, and "He" was the angel of the Jacob Family in the Fourth Epoch — the era in which that house stood among the five great families, alongside Abraham, Antigonus, Amon, and Tamara, that raised the Tudor Empire and answered to none but the Blood Emperor. Yet somewhere in that epoch Jacob was quietly devoured. Amon killed "Him" without a soul noticing, swallowing "His" fate, identity, and Beyonder characteristic to seize the Sequence 1 potency of Error, then wore "His" face — masquerading as the family''s ancestor and watching "His" descendants panic at their patriarch''s disappearance. The dead angel became a doorway: at the place where Tudor became the Blood Emperor, Amon buried a false treasure trove passed off as Jacob-Family heirloom, a thousand-year trap that finally lured Pallez Zoroast to his end and yielded the last Sequence 1 characteristic of the pathway. Jacob endures now only as a stolen name and a coat of arms of three fingers spread as hour, minute, and second hands — the scattered survivors long since hidden away as the Hermits of Fate.', 'error', 5, null, ARRAY['Jacob'], ARRAY[1], ARRAY['error-pathway', 'angel', 'spoiler', 'jacob-family', 'tudor-empire', 'deceased', 'fourth-epoch'], 228),
  ('npc-zoroast', 'Zoroast — Worm of Time', 'npc', 'Zoroast was the first angel of the Zoroast Family and its Fourth-Epoch ancestor, an Error-pathway being who rose to Sequence 1, the Worm of Time. At that pinnacle the pathway''s core skill of "Theft" — which begins as the pilfering of physical objects and deepens across the sequences to fate, identity, self-awareness and Beyonder characteristics at Sequence 2, the Trojan Horse of Destiny — could reach further still, temporarily seizing time itself, anchors, and the very authorities of Uniqueness. The Ancient Sun God named the archetype for what it is: a trojan horse of fate, the worm of time, the loophole in rules, the manifestation of all errors. Once human, "He" was reckoned a mythical creature by the end. Zoroast fell amid the conflicts of the Warring Era, but through the intervention of Solomon — who in that age had not yet ascended to godhood — the Zoroast Family did not lose "His" Beyonder characteristics, and so the lineage endured through descendants such as Pallez Zoroast and the now-dead Mobet Zoroast. Bound to the Zoroast Family and the Solomon Empire, Zoroast is long deceased, a foundational error whose stolen authority still flows down the bloodline.', 'error', 5, null, ARRAY['Zoroast'], ARRAY[1], ARRAY['error-pathway', 'angel', 'spoiler', 'worm-of-time', 'zoroast-family', 'solomon-empire', 'fourth-epoch', 'deceased'], 230),
  ('npc-kotar', 'Kotar — The God of Wishes', 'npc', 'Kotar is a Dark Demonic Wolf, a black-furred, eight-legged beast four to five meters tall, a tuft of grayish-white fur upon its forehead and pupils of pure black. In the Second Epoch it was a Subsidiary God of the Annihilation Demonic Wolf Flegrea, worshipped as the God of Wishes — "The Dark Lord that exists alongside History, the Embodiment of Countless Miracles." It holds one of the nine Sequence 2 Miracle Invoker Beyonder characteristics of the Fool Pathway. Cowardly yet daring, placing its own survival above all else, it endured from the Second Epoch into the Fifth by fleeing rather than fighting. After Flegrea''s death it was hunted for centuries by Amon across the Forsaken Land of the Gods. When Sefirah Castle spat out a black velvet ''Curtain'' bearing the Fool Pathway''s Sequences 9 to 1 into the Forsaken Land in 1349, Kotar seized it and fled to Nois City, turning the inhabitants into marionettes to prepare its advancement to Sequence 1, Attendant of Mysteries — until it sensed Amon and the True Creator and hurriedly migrated. Tracked by Klein Moretti on the Evernight Goddess''s intelligence, Kotar was defeated, feigned suicide to abandon the Curtain, then revived itself and fled once more. Over three thousand years old, it endures still.', 'fool', 5, null, ARRAY['Kotar', 'God of Wishes'], ARRAY[2], ARRAY['fool-pathway', 'angel', 'spoiler', 'subsidiary-god', 'demonic-wolf', 'flegrea', 'miracle-invoker'], 225),
  ('npc-true-creator', 'True Creator — The Lord who Reigns Behind the Curtain of Shadows', 'npc', 'The True Creator is the Sequence 0 god of the Hanged Man Pathway, holding that Pathway''s Uniqueness and the authority of Degeneration. "He" is no true creator but a fallen one — an evil spirit of the Ancient Sun God, born on the first day of the Fourth Epoch after Rose Redemption killed the corrupted Ancient Sun God and the traitor Angels feasted on His remains. In dying, He seized only Sasrir''s personality, the Hanged Man characteristics, and the extreme emotions of His fall, and was reborn in His own corpse. Worshipped as the god who "endured all sins to save the world," He most often manifests as a giant hanged upside-down on a cross behind a shadow veil — His confirmed true form. Because He carries the Ancient Sun God''s negative self, steeped in the Chaos Sea, His strength once exceeded a normal Sequence 0, until the Seven Orthodox Deities gravely wounded and sealed Him during the War of the Four Emperors. He backed the Solomon Empire''s Church of the True Creator and commands the serpent Ouroboros; in the Fifth Epoch the Aurora Order and Iron and Blood Cross Order revere Him. By Circle of Inevitability He and Adam — the Ancient Sun God''s divinity side — have fully fused, Adam becoming the current True Creator.', 'hanged-man', 5, null, ARRAY['True Creator', 'Fallen Creator', 'The Hanged Man', 'Grisha'], ARRAY[0], ARRAY['hanged-man-pathway', 'deity', 'spoiler', 'rose-redemption', 'aurora-order', 'ancient-sun-god', 'solomon-empire'], 238),
  ('npc-sasrir', 'Sasrir — The Dark Angel', 'npc', 'Sasrir, the Dark Angel, was the first angel the Ancient Sun God ever made — "His" left hand, "His" proxy, the Deputy of Heaven, and leader of the eight Kings of Angels, the one closest to the Lord. Soon after the Sun God rose from the Chaos Sea, sensing the Primordial God Almighty might wake within "His" body, "He" cut away part of "His" own darkness and negative personality and, with one of "His" ribs, forged Sasrir — vesting in "Him" the Authority of Degeneration, the characteristics of the Hanged Man Pathway, and the First Blasphemy Slate, so "He" might wield the Chaos Sea and hold corruption apart from "Himself." As the Sequence 1 Dark Angel of that pathway, Sasrir conspired with the Evernight Goddess to found the Rose Redemption, a plot to slay the Sun God and cleanse the Primordial One through resurrection. In the Giant King''s Court "His" consciousness returned into the Lord, but the Wisdom, White, and Wind Angels betrayed the design and feasted on the corpse — the Feast of Betrayal that forced rebirth as the True Creator. The obsession left behind festered in the Forsaken Land of the Gods as an Evil Spirit, finally cut down by Klein Moretti, Colin Iliad, Lovia Tiffany, and Derrick Berg in Fall 1352 of the Fifth Epoch.', 'hanged-man', 5, null, ARRAY['Sasrir', 'Dark Angel', 'Sassy', 'Nie Zhen'], ARRAY[1], ARRAY['hanged-man-pathway', 'sequence-1', 'king-of-angels', 'angel', 'spoiler', 'rose-redemption', 'ancient-sun-god', 'evil-spirit', 'deceased'], 232),
  ('npc-steph', 'Steph — Angel of the Holy Word', 'npc', 'Steph, called the Angel of the Holy Word, is a Sequence 2 Profane Presbyter of the Hanged Man Pathway — an Angel who serves as attendant and Blessed of the True Creator. He is a subordinate of Ouroboros, the Angel of Fate, and a member of the Aurora Order, a latter-day cult whose lineage traces back to Rose Redemption — the Third-Epoch alliance of Kings of Angels and Gods, from whose remnant the worship of the True Creator descends. He wears the seeming of an old priest: nearly two point three meters tall with a slight hunch, grizzled hair, wrinkles at the corners of his eyes, a scar at the corner of his mouth, and calm dark-brown eyes, robed in a long black clergyman''s vestment. In his other form he swells to four meters, and behind him unfold four pairs of gloomy yet holy illusory wings of black feathers, their shadows crossing. The power of degeneration shields him from the darkness. In the Forsaken Land of the Gods, at Nois City, he confronted Klein Moretti — naming him the one who shattered the son of God''s descent ritual and twice interfered with the Lord''s descent, marking him as prey. He remains alive.', 'hanged-man', 5, null, ARRAY['Steph', 'Angel of the Holy Word'], ARRAY[2], ARRAY['hanged-man-pathway', 'angel', 'spoiler', 'rose-redemption', 'aurora-order', 'true-creator'], 216),
  ('npc-retia-austin', 'Retia Austin — The Dragon Scholar', 'npc', 'Retia Austin is a Sequence 2 "Sage" of the Hermit Pathway — a taciturn, wine-haired woman in a loose black robe whom even Cattleya, the Tarot Club''s own Hermit, sensed as something strange among warlocks. For centuries she pored over the remains of dragons, earning within the Moses Ascetic Order the name Dragon Scholar. That study became flesh: at the information level she learned to rewrite herself into a giant dragon five or six meters tall, her still-human head magenta above amber vertical pupils, a long tailbone of joints and barbs unfurling behind, powerful and exuding an evil beauty — vitality and strength purchased through knowledge. She rose to Vice Chairman of the Moses Ascetic Order and stood among its Ten Pillars, that Fourth-Epoch secret order of ascetics who worshipped the Hidden Sage, once respectable seekers of knowledge long since corrupted into an evil cult. When the Tarot Club and its allies moved to Hunt the Hidden Sage in the Fifth Epoch, Retia fought Cattleya and Bernadette Gustav at the Order''s Avalon headquarters in the North Sea. The Order fell — but she alone slipped free of the slaughter, a living dragon still loose in the world.', 'hermit', 5, null, ARRAY['Retia Austin', 'Dragon Scholar'], ARRAY[2], ARRAY['hermit-pathway', 'angel', 'spoiler', 'moses-ascetic-order', 'hidden-sage'], 216),
  ('npc-torriope', 'Torriope — Chairman of the Moses Ascetic Order', 'npc', 'Torriope is a Sequence 2 Sage of the Hermit Pathway, Chairman and one of the Ten Pillars of the Moses Ascetic Order — the once-respectable brotherhood of knowledge-seekers, founded in the Fourth Epoch by Stiano and a few other humans who had read the Second Blasphemy Slate, that curdled into a cult after its god, the Hidden Sage, came to life and corrupted it. An Angel who advanced in the middle-to-late Fourth Epoch, Torriope was not a founding member, yet he endured more than a thousand years, witnessing countless mystical events, mastering vast arcane lore, and forging several powerful spells of his own. His masterwork is Avalon, the Order''s hidden headquarters in the North Sea, which he created through Mystical Re-enactment. Robed and cowled in a warlock''s black hood, he embodies the Order''s ascetic secrecy: silence, discipline, and the relentless pursuit of forbidden knowledge under the shadow of the god that hunts its own faithful. His long vigil ends in the Fifth Epoch when the Tarot Club opens its campaign to hunt the Hidden Sage; assailed at Avalon by Fors Wall, the Magician, and by the God of Steam and Machinery, Torriope is slain — a Pillar toppled, and the Order''s fall drawing near.', 'hermit', 5, null, ARRAY['Torriope'], ARRAY[2], ARRAY['hermit-pathway', 'angel', 'spoiler', 'moses-ascetic-order', 'hidden-sage', 'deceased'], 218),
  ('npc-trunsoest', 'Trunsoest — The Night Emperor', 'npc', 'Trunsoest, the Night Emperor, was the ancestor of the Trunsoest Family — a brass-haired, gold-eyed figure of scholarly aspect, seeming barely past twenty though "He" was born after the Third Epoch, before the first Solomon Empire, and rose to power in the Fourth. Once a Sequence 1 Prince of Abolition of the Black Emperor Pathway, "He" was forced to abandon that road when the Black Emperor Solomon resurrected, switching instead to the Justiciar Pathway. With the support of the Six Orthodox Gods "He" climbed to its summit, becoming the Sequence 0 Justiciar — a true god. "His" marriage to the Blood Moon Queen Auernia won "Him" the loyalty of the Sanguines, and the two, the author confirms, came to develop genuine feelings for each other despite the political match. After the Black Emperor''s fall "He" and the Blood Emperor Alista Tudor founded the Tudor-Trunsoest United Empire over the Northern Continent, before Trunsoest broke away to raise the Trunsoest Empire alone. "He" once tried and failed to shatter the Sealed Artifact 0-05, the Magic Wishing Lamp — a failure tied to the corruption of the Trunsoest Brass Book. "He" perished in the War of the Four Emperors, though the empire "He" built outlived Him.', 'justiciar', 5, null, ARRAY['Trunsoest', 'Night Emperor'], ARRAY[0], ARRAY['justiciar-pathway', 'deity', 'spoiler', 'trunsoest-family', 'four-emperors', 'switched-pathways', 'fourth-epoch'], 232),
  ('npc-dlink-augustus', 'Dlink Augustus — The Balancer', 'npc', 'Dlink Augustus, former Duke of Southville, is a Sequence 2 Balancer of the Justiciar Pathway and one of the last living Angels of the Augustus Family, the royal house of the Loen Kingdom. A slightly arrogant elder — black hair threaded with silver, clean-shaven — "he" is spoken of in the guarded quotation marks reserved for those whose selfhood the higher Sequences have complicated. His bloodline descends from the family''s ancestor, William Augustus I, back through the collapse of empires: the Solomon Empire, the Tudor-Trunsoest United Empire, and the Trunsoest Empire, until the Augustus line — backed by the Lord of Storms and the Evernight Goddess — carved the Loen Kingdom from the ruins. As Balancer he wields the Justiciar''s high arts of law and order: verdict, punishment, the negation of other Beyonders'' powers, the enforcement of balance upon chaos. In the Fifth Epoch, when the family conspired with the Twilight Hermit Order and others to work George III''s Apotheosis Ritual, Dlink appeared within the secret mausoleum in Awwa County to confront the Historical Void projection of Klein Moretti and Azik Eggers. By 1350 the Augustus Family kept but three Angels; with George III''s death, only Dlink and the ancestor William remain. He lives still.', 'justiciar', 5, null, ARRAY['Dlink Augustus'], ARRAY[2], ARRAY['justiciar-pathway', 'angel', 'spoiler', 'augustus-family', 'loen-kingdom', 'balancer'], 235),
  ('npc-tamara', 'Tamara — Ancestor of the Tamara Family', 'npc', 'Tamara was the ancestor of the Tamara Family, an angel of the Justiciar Pathway who rose in the Fourth Epoch. Once human, "he" became a Mythical Creature — a figure of eerie, almost waxen symmetry, gray-eyed and black-haired, every part of the body concisely mirrored. His house was one of the five great families — with Abraham, Antigonus, Amon, and Jacob — that raised the Tudor Empire under the Blood Emperor, holding a hereditary duke''s title and roots reaching back to the renowned nobility of the older Solomon Empire. The Tamara Family controlled the Justiciar Pathway, the discipline of Order, verdict, and punishment; only later, through long marriage alliances with the Abraham Family, did the line also inherit the Door Pathway. But before the War of the Four Emperors, Tamara suffered some corruption — the seed of the Mirror People, for his descendants can still spawn reflections in the Mirror World that supplant their real selves. In that same war the Blood Emperor perished and Tamara died, and the surviving Angel Families were hunted from their pedestals by the Seven Deities. He is long dead, yet his fracture endures in every branch that bears his name.', 'justiciar', 5, null, ARRAY['Tamara'], ARRAY[2], ARRAY['justiciar-pathway', 'angel', 'spoiler', 'tamara-family', 'tudor-empire', 'fourth-epoch', 'mirror-people'], 215),
  ('npc-auernia', 'Auernia — The Blood Moon Queen', 'npc', 'Auernia is the symbol of beauty made flesh — were there a mirror that answered "who is the fairest of them all," her name would be its only reply. A Sanguine of the Moon Pathway, she rose in the Second Epoch as the Subsidiary Goddess of the Sanguine Ancestor Lilith, the Goddess of Beauty at Sequence 1 "Beauty Goddess," for Lilith held but a single Beauty Goddess Characteristic and the Uniqueness of the Moon. When Lilith fell, Auernia turned to the faction of the Elf King Soniathrym, and though Lilith''s Characteristic was reclaimed as a Sanguine sacred object, she dared not ascend recklessly in the age before the First Blasphemy Slate. In the Fourth Epoch, with the Ancient Sun God''s fall making Sequence 0 vital and the rank of King of Angels exalted, she concocted a potion from that sacred object and rose to become a King of Angels bearing two Sequence 1 Beauty Goddess Characteristics. She became the Blood Moon Queen, wife of the Night Emperor Trunsoest and Empress of the Trunsoest Empire, gathering the Sanguines as pillars of the dynasty; a political marriage that ripened into true feeling. She perished with her Emperor in the War of the Four Emperors. One of her Characteristics passed to the Earth Mother; the other, stolen by the Rose School of Thought, became the Shadow of the Beauty Goddess.', 'moon', 5, null, ARRAY['Auernia', 'Blood Moon Queen', 'Goddess of Beauty'], ARRAY[1], ARRAY['moon-pathway', 'king-of-angels', 'angel', 'spoiler', 'sanguines', 'trunsoest-empire', 'beauty-goddess', 'subsidiary-god'], 255),
  ('npc-olmer', 'Olmer — Round Moon Duke', 'npc', 'Round Moon Duke Olmer is one of the three Dukes of the Sanguine, a Sequence 2 "Life-Giver" of the Moon Pathway who has existed since before the Cataclysm of the Third Epoch. Born in the Second Epoch and reckoned at least five thousand years old, "He" once followed in the footsteps of the Sanguine Ancestor Lilith for several centuries — until "She" met "Her" demise eight to nine hundred years before that epoch''s close. Though an Angel''s lifespan far outstrips a common Beyonder''s, even Olmer must lie within a coffin to prolong "His" waning years. Bound to the Sanguines and the Church of the Earth Mother, "He" reveres Lilith as ancestor while warring against the Rose School of Thought''s Indulgence and Primordial Moon factions and the believers of the Primordial Moon. In Backlund "He" came in person for Emlyn White, tasking him to hunt Primordial Moon worshippers and recover Lilith''s holy artifact, and personally purified the Scarlet Scholar Characteristic Emlyn bore. During the Apocalypse, "He" stood with the other Sanguine Dukes against the Outer Deities to shield a distant world. Alexis numbered among "His" now-dead descendants.', 'moon', 5, null, ARRAY['Olmer', 'Duke Olmer', 'Round Moon Duke Olmer', 'Round Moon'], ARRAY[2], ARRAY['moon-pathway', 'angel', 'spoiler', 'sanguine', 'church-of-the-earth-mother'], 215),
  ('npc-lilith-earth-mother', 'Lilith — The Earth Mother', 'npc', 'Lilith is the Source of Life and the Mother of All Things — one of the rare Survivors who lived through the Pre-Epoch Earth Cataclysm. In the Second Epoch she rose as an Ancient Goddess of the Moon Pathway, the Sanguine Ancestor whose bat wings half-eclipse the crimson moon, holding the Moon''s Uniqueness and a single Sequence 1 Beauty Goddess Characteristic; the Sanguines revere her still as ancestor and god. Betrayed by Giant King Aurmir at the Early Era of Fire, she was believed slain — yet she faked her death, and with the Evernight Goddess''s Concealment and the Ancient Sun God''s Error authority stole the fate of the Giant Queen Omebella to become the Earth Mother, ascending to Sequence 0 "Mother" of the Mother Pathway. In the Third Epoch she joined Rose Redemption within the Subsidiary Gods faction under the Evernight Goddess, favouring giants — her Blessed were Feysacians — and later drew her Divine Kingdom into the Astral World to mend the cracked barrier. In the Fifth Epoch''s 1350 World War she stabbed the God of Combat in the back and reclaimed the Moon''s Uniqueness, then shielded Klein''s Apotheosis. When Omebella''s true birth destabilized her, she prepared herself as a symbolic weapon — slain by Lumian Lee in the summer of 1360 to sever the Mother Goddess of Depravity from the Brood Hive.', 'mother', 5, null, ARRAY['Lilith', 'Earth Mother', 'Sanguine Ancestor', 'Omebella'], ARRAY[0], ARRAY['mother-pathway', 'sequence-0', 'deity', 'spoiler', 'ancient-gods', 'sanguines', 'church-of-the-earth-mother', 'moon-pathway', 'rose-redemption'], 232),
  ('npc-omebella', 'Omebella — The Desolate Matriarch', 'npc', 'Omebella, the Goddess of Harvest, is a Sequence 2 Angel of the Mother Pathway — the Desolate Matriarch — and, uniquely, a same-pathway Boon Recipient. Born in the mid-First Epoch to the Primordial God Almighty and the Brood Hive alongside her younger twin brother Zedus (a Sequence 2 Moon Pathway Angel), she was a female Giant, Giant Queen and Subsidiary Goddess to her husband, the Giant King Aurmir, worshipped from the Giant King''s Court to the Kingdom of Silver that would become the City of Silver. She wore two faces: one of light — the harvest''s grace, life''s precious embrace, ensuring bounty and swelling populations — and one of desolation, demanding rivers of human sacrifice, for extreme harvest is inevitably accompanied by extreme desolation. In the Second Epoch, Aurmir sent her and her son Badheil against Elf King Soniathrym and the Queen of Calamity Cohinem. She died at that epoch''s end, betrayed and drained by the City of Silver''s own believers when she came begging life force — but her identity and destiny were stolen by Lilith, who took her place as Earth Mother, a theft Klein suspected the Ancient Sun God and Evernight Goddess enabled. Her corpse became the Grade 0 Sealed Artifact, the Gift of the Land, owned by the City of Silver.', 'mother', 5, null, ARRAY['Omebella', 'Goddess of Harvest', 'Desolate Matriarch', 'Child of God'], ARRAY[2], ARRAY['mother-pathway', 'angel', 'spoiler', 'deity', 'goddess-of-harvest', 'city-of-silver', 'giant-kings-court', 'boon-recipient', 'brood-hive'], 224),
  ('npc-god-of-steam-and-machinery', 'God of Steam and Machinery — Guardian of Craftsmen', 'npc', 'The God of Steam and Machinery is the Sequence 0 True God of the Paragon Pathway, a Mythical Creature once the human Yuggs Stiano who beheld the Second Blasphemy Slate after it emerged near the beginning of the Fourth Epoch. As the God of Craftsmanship he helped found the Moses Ascetic Order before leaving it, then seized a crucial moment in the War of the Four Emperors to ascend — the weakest of the seven Orthodox Gods, for he had not digested his Sequence 1 Illuminator potion before promotion and must ever guard his sanity. With the Lord of Storms and the Evernight Goddess he backed the Augustus Family to raise the Loen Kingdom, and moved his divine kingdom into the Astral World to mend the cracked Astral Barrier. In the Fifth Epoch, Roselle Gustav''s Industrial Revolution let him recast his title from Craftsmanship to Steam and Machinery. Ally of the Fool through the Fool''s Dream, he stood at Klein''s apotheosis and, after the Hidden Sage''s death, received the Hermit Pathway''s Uniqueness. In the Apocalypse — as the Celestial Master''s true disciple bearing the Dao Name True Blessing — he could not become the Demon of Knowledge, so he joined the Celestial Master''s formation for temporary quasi-Great Old One strength against the Outer Deities. Honored as the Embodiment of Essence, Guardian of Craftsmen, Brilliance of Technology, he dwells in the Astral World, alive.', 'paragon', 5, null, ARRAY['God of Steam and Machinery', 'God of Craftsmanship', 'Yuggs Stiano', 'Stiano', 'The Artisan', 'True Blessing'], ARRAY[0], ARRAY['paragon-pathway', 'deity', 'spoiler', 'orthodox-gods', 'church-of-the-god-of-steam-and-machinery', 'moses-ascetic-order', 'hermit-uniqueness'], 232),
  ('npc-einhorn', 'Einhorn — The Conqueror', 'npc', 'Einhorn was the ancestor of the Einhorn Family in the Fourth Epoch, a Sequence 1 Conqueror standing at the apex of the Red Priest Pathway. Founder and Leader of "his" bloodline — though, according to the author, Einhorn was originally a woman — this angel served the Trunsoest Empire and belonged among the three who held the pathway''s summit alongside Sauron and Medici. Pallez Zoroast records that "They" were absolute archenemies, the sort who could not tolerate one another''s very existence. In the Fourth Epoch, with the backing of Adam and Amon, Alista Tudor slew all three angels — Sauron, Einhorn, and Medici — to ascend to the seat of Red Priest, and Einhorn perished on July 29, Year 510 of the Fourth Epoch. Yet the grave did not hold "her." The remnant souls of the three fused into a single Evil Spirit, the Red Angel Evil Spirit known as Sauron-Einhorn-Medici — three beings stuffed into one body, forced to unanimous accord or fall to internal strife. When Alista Tudor at last perished, the Einhorn Family reclaimed their ancestor''s Beyonder characteristic, drawing the Conqueror''s power back into the line that still bears her name.', 'red-priest', 5, null, ARRAY['Einhorn', 'Sauron-Einhorn-Medici'], ARRAY[1], ARRAY['red-priest-pathway', 'angel', 'spoiler', 'einhorn-family', 'trunsoest-empire', 'evil-spirit', 'fourth-epoch', 'conqueror'], 232),
  ('npc-medici', 'Medici — The War Angel', 'npc', 'Medici is the Red Angel and the War Angel, one of the eight Kings of Angels who served the Ancient Sun God from the Second Epoch, where "He" warred against powerful dragons. An innate Mythical Creature born at Sequence 2, "He" rose to Sequence 1 "Conqueror" of the Red Priest Pathway and accommodated its Uniqueness — enough that "His" three-line Honorific Name (the Great God of War, the Symbol of Iron and Blood, the Ruler of Chaos and Strife) reached toward the register reserved for true gods. Black-armored and blood-splashed, red-haired as fire, "He" led the Red of War Army, whose every soldier could merge minds with "Him" into one. "He" joined the Rose Redemption, hastening the Ancient Sun God''s fall, then followed the True Creator alongside Ouroboros. In the Fourth Epoch "He" stood among the highest nobles of the Solomon Empire. In that era''s middle, Alista Tudor — aided by Adam and Amon — hunted the Red Priest apex; ambushed while dealing with Sauron, Medici was the first of the three archenemies to die, on July 29, Year 510, and the Blood Emperor ascended to Sequence 0. "His" remnant spirit fused with Sauron''s and Einhorn''s beneath Backlund into the Evil Spirit Sauron-Einhorn-Medici, where "He" endures as the primary consciousness. "He" once carried the infant Amon, whom "He" called Lil'' Raven.', 'red-priest', 5, null, ARRAY['Medici', 'Red Angel', 'War Angel', 'Sauron-Einhorn-Medici'], ARRAY[1], ARRAY['red-priest-pathway', 'king-of-angels', 'angel', 'spoiler', 'rose-redemption', 'medici-family', 'solomon-empire', 'evil-spirit', 'deceased'], 245),
  ('npc-sauron', 'Sauron — The Conqueror', 'npc', 'Sauron was the ancestor and founder of the Sauron Family, a Sequence 1 Conqueror standing at the very apex of the Red Priest Pathway — the pathway of War and Destruction, whose Tarot is the Chariot. In the Fourth Epoch "he" reigned as one of three angels who crowned that pathway, alongside Einhorn and Medici; yet the three of Them were absolute archenemies, the kind who could not abide one another''s existence. The author has confirmed Sauron was originally a woman. When Alista Tudor moved to seize the throne of Red Priest — backed by Adam and Amon — it was Medici''s snare that undid Sauron: while Medici was occupied dealing with Sauron, Alista Tudor fell upon them both. On July 29, Year 510 of the Fourth Epoch, Alista Tudor killed all three. In death their remnant souls did not disperse but fused, curdling together into the Evil Spirit known as Sauron-Einhorn-Medici — enemies bound eternally in one wailing shape. Sauron thus endures only as a fragment of that horror, while the Sauron Family, once affiliated with the Trunsoest Empire, later reclaimed their ancestor''s Beyonder characteristic after Alista Tudor''s own fall.', 'red-priest', 5, null, ARRAY['Sauron', 'Sauron-Einhorn-Medici'], ARRAY[1], ARRAY['red-priest-pathway', 'angel', 'spoiler', 'sauron-family', 'trunsoest-empire', 'fourth-epoch', 'evil-spirit', 'deceased'], 225),
  ('npc-sauron-einhorn-medici', 'Sauron-Einhorn-Medici — The Red Angel Evil Spirit', 'npc', 'Sauron-Einhorn-Medici — the Red Angel Evil Spirit, more simply Medici — is not one being but three angels crammed into a single ruined body: Sauron and Einhorn, both Sequence 1 "Conquerors" and ancestors of their namesake families, and Medici, a King of Angels who once followed the Ancient Sun God in the Third Epoch and rose to high nobility of the Solomon Empire. Archenemies in life, the three were hunted, ambushed, and slain in the mid-Fourth Epoch by Alista Tudor — abetted by Adam and Amon — who devoured "Their" Beyonder Characteristics and the Red Priest Uniqueness to reach Sequence 0. Their remnant spirits fused in the Tudor-Trunsoest Underground Ruins beneath Backlund into one bloodstained, decaying evil spirit whose cheeks bear two extra mouths, each angel demanding unanimity before "They" may act. Because Medici once bore the pathway''s Uniqueness, "He" still wields the three-line Honorific Name meant for true gods: the Great God of War, the Symbol of Iron and Blood, the Ruler of Chaos and Strife. Whose coming, the Evernight Goddess warned, spells the raising of arms. After 2,081 years, allying with the Eternal Blazing Sun, "He" reclaims a Conqueror characteristic and ascends once more to King of Angels — the most formidable Conspirer, returned.', 'red-priest', 5, null, ARRAY['Sauron-Einhorn-Medici', 'Medici', 'Red Angel Evil Spirit', 'Sauron', 'Einhorn'], ARRAY[1], ARRAY['red-priest-pathway', 'king-of-angels', 'angel', 'spoiler', 'evil-spirit', 'medici-family', 'sauron-family', 'einhorn-family'], 230),
  ('npc-eternal-blazing-sun', 'Eternal Blazing Sun — The White Angel Aucuses', 'npc', 'The Eternal Blazing Sun is the Sequence 0 God of the Sun Pathway — Inextinguishable Light, Embodiment of Order, God of Contracts, Guardian of Businesses — worshipped by the Church of the Eternal Blazing Sun and the faith of the Intis Republic. In truth "He" was born Aucuses, the White Angel, one of the eight Kings of Angels who served the Ancient Sun God through the Third Epoch, rising from humble beginnings. He betrayed his lord, aligning with the Rose Redemption under Dark Angel Sasrir to bring about the Ancient Sun God''s downfall, then seized the chaos of the divine war and, aided by the Evernight Goddess, ascended to Seq 0. In the Fourth Epoch he raised the Sauron Family to found the Intis Kingdom; he clashed with the Lord of Storms and the God of Knowledge and Wisdom over their neighboring pathways yet reached a common accord with the other Orthodox Gods, remaining hostile to both. When Earth''s barrier cracked, "He" moved his divine kingdom into the Astral World to mend it. Proud above all, "He" bore the Primordial God Almighty''s reviving consciousness within Himself, harnessing the Chaos Sea only warily alongside his ally Medici. In late 1359 of the Fifth Epoch, after his daughter Omebella''s birth strengthened that alien god, "He" chose to die by the Evernight Goddess''s hand rather than dissolve — preferring to perish as a god than linger, lost.', 'sun', 5, null, ARRAY['Eternal Blazing Sun', 'Aucuses', 'White Angel'], ARRAY[0], ARRAY['sun-pathway', 'deity', 'spoiler', 'kings-of-angels', 'rose-redemption', 'church-of-the-eternal-blazing-sun', 'orthodox-gods', 'intis-republic'], 240),
  ('npc-god-of-combat', 'God of Combat — The Great Knight God', 'npc', 'The God of Combat is Badheil, Sequence 0 "Twilight Giant" of the Twilight Giant Pathway and enthroned deity of the Church of the God of Combat — "Symbol of Power and Glory, the Great Knight God; Master of War, Patron of Guns; Twilight of All Things." Born the God of Dawn in the Second Epoch, eldest son of Giant King Aurmir and the Goddess of Harvest Omebella, He inherited His father''s divine position, then completed apotheosis in the early Third Epoch. Joining Rose Redemption''s Subsidiary Gods faction under the Evernight Goddess, He helped orchestrate the assassination of the Ancient Sun God — the battle remembered as the Cataclysm, which also claimed His younger brother Bladel. As one of the Six, later Seven, Orthodox Gods, He raised the Church of the God of Combat and backed the Einhorn Family into the Feysac Kingdom. A mountain-tall figure in tattered silver armor, eyes a blob of orange light behind a visor, He wields a colossal Twilight Sword. In summer 1350, provoked by Evernight''s seizure of the Death Uniqueness, He launched the 1350 World War, hurling Feysac against Loen. In 1352, in Backlund, Earth Mother — Lilith in disguise — drove a wooden staff through His heart, and Evernight finished Him, taking the Twilight Sword. His deceased body''s scattered characteristics still birth Twilight Giant monsters.', 'twilight-giant', 5, null, ARRAY['God of Combat', 'Badheil', 'God of Dawn'], ARRAY[0], ARRAY['twilight-giant-pathway', 'deity', 'spoiler', 'orthodox-gods', 'rose-redemption', 'subsidiary-gods', 'church-of-the-god-of-combat', 'feysac-empire', 'deceased'], 235),
  ('npc-bladel', 'Bladel — The God of Glory', 'npc', 'Bladel, the God of Glory, is a Sequence 2 "Glory" of the Twilight Giant Pathway — youngest son of the Giant King Aurmir and the Goddess of Harvest Omebella, and a Subsidiary God of his father''s Giant King''s Court in the Forsaken Land of the Gods. A single-eyed giant towering tens of meters, bluish-black pupil sunken and lifeless, he committed the unforgivable: he publicly insulted, publicly cursed the Ancient Sun God. For that blasphemy the Sun God cursed and exiled him, and when the Cataclysm ended the Third Epoch and slew him, the curse denied him even the mercy of death — his corpse would not decay, his soul was bound fast to rotting flesh. For over 2,580 years the bound corpse wandered Chernobyl, dark-green and weeping pus, grayish-yellow gas seeping from its wounds to curse all who touched it. In December of 1350, Fifth Epoch, the Evernight Goddess turned her Authority of Death upon that corpse, seizing control of it to help Klein Moretti escape Amon. Afterward Amon — a King of Angels — "stole" the curse itself, and Bladel was at last laid to rest: the flesh crumbled to bare bone, and his imprisoned soul was finally, mercifully freed.', 'twilight-giant', 5, null, ARRAY['Bladel', 'God of Glory'], ARRAY[2], ARRAY['twilight-giant-pathway', 'angel', 'spoiler', 'subsidiary-god', 'giant-kings-court', 'forsaken-land-of-the-gods'], 232),
  ('npc-lord-of-storms', 'Lord of Storms — King of the Skies, Emperor of the Seas', 'npc', 'The Lord of Storms is the Sequence 0 God of the Tyrant Pathway, whose honorific name proclaims Him King of the Skies, Emperor of the Seas, Lord of the Calamity, and God of the Storms. His true name is Leodero — once the Wind Angel, one of the eight Kings of Angels serving the Ancient Sun God through the Third Epoch, who followed his master from weakness into power before joining Rose Redemption in the plot that brought the Ancient Sun God''s death, and from that ruin ascended to Tyrant''s Sequence 0. Orthodox legend names Him one of three gods formed from the Original Creator''s spirit, who — alongside the Evernight Goddess, the Earth Mother, and the God of Combat — shepherded humanity through the Cataclysm; the Evernight Goddess remains His enduring ally. In the Fourth Epoch He raised the Augustus Family to found the Loen Kingdom, then withdrew His divine kingdom to the Astral World, leaving the Chasm of Storms on Pasu island as His Church''s altar. Sailors and pirates worship Him across the seas. He smote George III''s failed apotheosis, scoured Adam''s Corpse Cathedral with lightning, and in the Apocalypse — refusing to surrender or self-destruct — became entangled ball lightning and hurled Himself at the Mother Goddess of Depravity''s crimson moon, dying to tear a breach in it. The Fool then grafted His Beyonder Characteristics and the Tyrant Uniqueness to Grisha Adam.', 'tyrant', 5, null, ARRAY['Lord of Storms', 'Leodero', 'Wind Angel'], ARRAY[0], ARRAY['tyrant-pathway', 'deity', 'king-of-angels', 'spoiler', 'church-of-the-lord-of-storms', 'rose-redemption', 'orthodox-gods'], 240),
  ('npc-soniathrym', 'Soniathrym — The Elf King', 'npc', 'Soniathrym, the Elf King, is a Sequence 0 god of the Tyrant Pathway — one of the eight Ancient Gods of the Second Epoch, numbered among the quasi-humans. An elf born, as the Myth of Creation tells, from the lungs of the Original Creator, "He" wears a simple loose robe over pointed ears and a handsome face framed by thick hair of mingled black and blue, yet carries Himself with pure tyranny, as apt to hurl the electric spear leaning at His armrest as to speak. In the Early Era of Fire He stood with the Giant King Aurmir and the Sanguine Ancestor Lilith against the Dragon of Imagination Ankewelt, the Phoenix Ancestor Gregrace, the Mutated King Kvastir, the Devil Monarch Farbauti, and the Annihilation Demonic Wolf Flegrea. His wife is the Queen of Calamity Cohinem, one of His subsidiary gods alongside the Goddess of Beauty Auernia and the God of Luck. Believing Aurmir betrayed Lilith and caused Her to perish, He marched on the Giant King''s Court — and Aurmir, joined by a human secret cult led by the Goddess of Harvest Omebella and the God of Dawn Badheil, moved against Him. When the Ancient Sun God reclaimed His authorities, Soniathrym lost His godhood. Now only the Forsaken Land of the Gods remembers Him; the world crowned the Lord of Storms in His place.', 'tyrant', 5, null, ARRAY['Soniathrym', 'Elf King'], ARRAY[0], ARRAY['tyrant-pathway', 'deity', 'spoiler', 'ancient-gods', 'elves', 'second-epoch'], 232),
  ('npc-cohinem', 'Cohinem — Queen of Calamity', 'npc', 'Cohinem, the Queen of Calamity, is the Elf Queen — Subsidiary Goddess and wife of the now-dead Elf King Soniathrym, and a Sequence 2 "Calamity" of the Tyrant Pathway, though not a pure Angel of that Sequence. A Survivor of the Pre-Epoch Era, originating from the Western Continent that was home to the elves, "She" presumably merged with "Her" Beyonder Characteristic directly and went mad; by the time reason returned, the Western Continent had already been sealed away, and only later did "She" join Soniathrym and the remaining elves. An elf woman of timeless beauty, sharp-eared, black-haired in a bun, deep-brown eyes holding lightning within, "She" split "Her" Beyonder Characteristic into halves — one bound in the Book of Calamity, the other hidden elsewhere — for the Sequence 0 seat of the Tyrant Pathway was held by the Lord of Storms, "Her" enemy, whom "She" lacked the strength to oppose, and because the dwindling elves left "Her" anchors unstable. From within dreams "She" reaches Alger Wilson, offering the characteristic of a Cataclysmic Interrer should he carry the Book of Calamity to the Western Continent, which "She" claims will reappear as the apocalypse nears. "She" commands the elf Siatas, and is counted alive.', 'tyrant', 5, null, ARRAY['Cohinem', 'Queen of Calamity', 'Elf Queen'], ARRAY[2], ARRAY['tyrant-pathway', 'angel', 'spoiler', 'elves', 'subsidiary-god', 'pre-epoch'], 240),
  ('npc-adam', 'Adam — The Angel of Imagination', 'npc', 'Adam, the Angel of Imagination, wears the face of an innocent priest — white cloak, golden hair and beard, a silver cross, eyes as clear as a child''s — yet within him coils the divinity of the Ancient Sun God himself. Born in the Third Epoch as a Sequence 1 Author bearing the Uniqueness of the Visionary Pathway, he rose to become one of that Sun God''s Kings of Angels. When the Sun God perished and the traitors feasted on his remains, his divinity awoke inside Adam, who inherited it and disguised himself as the Child of the Creator. As leader and founder of the Twilight Hermit Order, he labors from the shadows toward his own advancement, hoarding Sequence 1 characteristics until, ritual complete, he ascends to Sequence 0 Visionary — the god called Visionary, the True Creator. His humanity — the extreme emotions of the Sun God''s death, driven to madness — was reborn separately as the True Creator, and the two halves warred over dominance before finally fusing, Adam prevailing. Elder brother and father-figure to Amon, ally to the Evernight Goddess and to the Fool he once opposed, he claws toward becoming a new God Almighty against the Outer Deities and the Primordial God Almighty. Killed by Lumian Lee; deceased.', 'visionary', 5, null, ARRAY['Adam', 'Angel of Imagination', 'True Creator', 'Grisha', 'Ancient Sun God'], ARRAY[0], ARRAY['visionary-pathway', 'sequence-0', 'deity', 'king-of-angels', 'spoiler', 'twilight-hermit-order', 'ancient-sun-god', 'true-creator'], 224),
  ('npc-ankewelt', 'Ankewelt — The Dragon of Imagination', 'npc', 'Ankewelt, the Dragon of Imagination, is one of the eight Ancient Gods of the Second Epoch and the god of the Visionary Pathway who held Sequence 0, with authority stretching also over the Paragon and White Tower Pathways as a mixed-pathway deity. A dragon formed alongside his kin from the brain of the Original Creator in the Myth of Creation, he was worshipped for a terrible power: whatever he imagined would manifest, the kingdoms he conceived descending upon the material world and the futures he declared inexorably coming true. From this power he conjured Liveseyd, the City of Miracles — a towering palace atop massive temple pillars, floating above the world — which later dwindled into myth. In the Early Era of Fire he warred alongside the Phoenix Ancestor Gregrace and the Mutated King Kvastir against the Giant King Aurmir, the Elf King Soniathrym, the Sanguine Ancestor Lilith, the Devil Monarch Farbauti, and the Annihilation Demonic Wolf Flegrea. When the Ancient Sun God reclaimed the authorities of the Ancient Gods, Ankewelt lost his godhood; the world forgot him and Visionary Adam took his throne — only the Forsaken Land of the Gods still remembers his name. His negative personality lingers as the Chaos Sea, sealed behind a bronze door within Liveseyd inside Groselle''s Travels. Scheming resurrection through the identities Alzuhod and Ariehogg and a Sequence 1 Author characteristic, his plan was undone by Adam''s interference.', 'visionary', 5, null, ARRAY['Ankewelt', 'Dragon of Imagination', 'Ariehogg', 'Alzuhod'], ARRAY[0], ARRAY['visionary-pathway', 'deity', 'spoiler', 'ancient-god', 'dragon', 'second-epoch', 'liveseyd', 'paragon-pathway', 'white-tower-pathway'], 235),
  ('npc-alzuhod', 'Alzuhod — The Dragon of Nightmare', 'npc', 'Alzuhod, the Dragon of Nightmare, was a Sequence 1 Author of the Visionary Pathway — a terrifying Mind Dragon of the Second Epoch who blanketed the sky beside his father, overlooking every powerful figure across land and sea. He is no true son but another self: the Dragon of Imagination Ankewelt, a Sequence 0 Visionary and Ancient God, split off one of his three Sequence 1 characteristics through the Envisioning power and shaped it into Alzuhod, a separate being of complete freedom whom Ankewelt could, by certain method or medium, fold back into himself. As Subsidiary God of Ankewelt, dwelling in Liveseyd, Alzuhod could seize the hearts of every living creature and bend them to his will while they believed the deeds their own, and he fabricated nightmares into waking reality. Loving cruel mischief, he let a prince kiss a rotted princess awake, bound girls into dancing shoes until death, and forged coincidences that dragged countless fates toward tragedy. He perished at the Rise of the Ancient Sun God, his sworn enemy, in the Second Epoch; his Sequence 1 characteristic congealed into the living Grade 0 Sealed Artifact, the Quill of Alzuhod — later destroyed by Adam to complete his own apotheosis.', 'visionary', 5, null, ARRAY['Alzuhod', 'Dragon of Nightmare'], ARRAY[1], ARRAY['visionary-pathway', 'angel', 'spoiler', 'dragons', 'subsidiary-god', 'second-epoch', 'mind-dragon'], 225),
  ('npc-ariehogg', 'Ariehogg — The Discerner', 'npc', 'Ariehogg is a mind dragon, a Sequence 2 Discerner of the Visionary Pathway, and — by "his" own telling — one of only three dragons to survive the Second Epoch. "His" body wears huge grayish-white stone scales, "his" eyes are pale-gold and vertical, and "his" bone wings hang like metallic leaf-veins beneath a gray, patterned membrane. Near five thousand years old, "he" is a Subsidiary God of the Dragon of Imagination Ankewelt — the Sequence 0 Visionary Ancient God of the Second Epoch, slain in the Rise of Ancient Sun God. "His" reaction on hearing of Liveseyd leads many to suspect Ariehogg is not merely Ankewelt''s subordinate but another self of that lost deity. "He" is the mind dragon worshiped by Hartlarkh Village in the Loen Kingdom''s East Chester County, dwelling within its Mind World; the Psychology Alchemists hunted "him" and failed. In Volume 7 "he" dragged Audrey Hall into a dream maze to probe the impression of Liveseyd "he" sensed upon her, only to be assailed by Mr. Wrath, who sought the truth of Adam''s identity. "Adam isn''t necessarily Adam," Ariehogg answered, "just like how I might not necessarily be Ariehogg." "He" endures still, alive.', 'visionary', 5, null, ARRAY['Ariehogg', 'Ankewelt', 'Dragon of Imagination'], ARRAY[2], ARRAY['visionary-pathway', 'angel', 'spoiler', 'dragon', 'subsidiary-god', 'second-epoch', 'ankewelt'], 222),
  ('npc-hermes', 'Hermes — The Discerner, Mr. Wrath', 'npc', 'Hermes is a Sequence 2 Discerner of the Visionary Pathway, an Angel who has walked the world since the Second Epoch — a living fossil of human mysticism who personally witnessed early Beyonders test the potions themselves, one thorny step at a time. "He" is the maker of the Hermes and Ancient Hermes languages that thread through all sorcery, and "He" retains a certain authority over his own tongue, able to strip the Hermes language of its power to shake natural forces. An old man with thick, wholly white hair and an unremarkable face, "He" conceals beneath his human clothes the shape of Mr. Wrath: a vast snow-white rabbit with burning red eyes. Once a member of the Twilight Hermit Order, "He" is the hidden founding influence behind the Psychology Alchemists — now returned as their new councilor, Mr. Wrath, master of Azshara in Lenburg. A former ally of Adam, "He" grew to doubt Adam''s true state, sought word from Ariehogg, and schemed to have Klein Moretti slay Pauli Derlau and shatter the Garden of Eden so "He" might rebuild the Alchemists under his own hand. "He" stood among the Beyonders opposing Klein at George III''s Apotheosis Ritual. "He" remains alive.', 'visionary', 5, null, ARRAY['Hermes', 'Mr. Wrath', 'Old Mister Hermes'], ARRAY[2], ARRAY['visionary-pathway', 'angel', 'spoiler', 'psychology-alchemists', 'twilight-hermit-order'], 225),
  ('npc-ouroboros', 'Ouroboros — The Angel of Fate', 'npc', 'Ouroboros, the Angel of Fate, is one of the eight Kings of Angels who once served the Ancient Sun God — a King of Angels of the Wheel of Fortune Pathway, holding Sequence 1, the Snake of Mercury, uniquely with two Sequence 1 Beyonder Characteristics. The Self-Devouring Mercury Giant Serpent, Spirit that Revolves this World, the Eyes that Look at Fate, the Great Prophet of Past, Present, and Future: silver-haired and soft-featured, "He" is a mythical creature over two and a half millennia old. A loyal follower since "He" was merely a Saint, "He" later joined Rose Redemption, whose rise felled that god, and after the other Kings scattered "He" led it, following the True Creator alongside Medici. Each rebirth begins again from a Snake Egg, growing back to "His" former form beside the Creator. Once among the highest nobles of the Solomon Empire in the Fourth Epoch, "He" hunted the God of Luck, blessed and rebooted fate, and left Arrodes to the True Creator when Adam came to fuse. Alive still, "He" walks the Fifth Epoch as the Sufferer hidden around Lumian, and as President Wu of the Aurora Order — reticent, unhurried, endlessly devouring "His" own tail.', 'wheel-of-fortune', 5, null, ARRAY['Ouroboros', 'Angel of Fate', 'Tail Devourer', 'Wu', 'Sufferer', 'Snake of Mercury'], ARRAY[1], ARRAY['wheel-of-fortune-pathway', 'king-of-angels', 'angel', 'spoiler', 'rose-redemption', 'aurora-order', 'solomon-empire'], 235),
  ('npc-god-of-knowledge-and-wisdom', 'God of Knowledge and Wisdom — The Dragon of Wisdom Herabergen', 'npc', 'The God of Knowledge and Wisdom is the Sequence 0 God of the White Tower Pathway, an omniscient hooded elder cradling an open book crowned by a single all-seeing eye, his sacred emblem — yet that pious mask conceals Herabergen, the Dragon of Wisdom. In the Second Epoch he was a Subsidiary God of the Dragon of Imagination Ankewelt; after Ankewelt''s death he turned to the Ancient Sun God and rose as the Wisdom Angel, one of the eight Kings of Angels of the Third Epoch. Amon names him the Dragon of Betrayal: he joined Rose Redemption under Dark Angel Sasrir, then with the Lord of Storms and Eternal Blazing Sun consumed the Ancient Sun God''s corpse to claim his godhood. Across the Fourth and Fifth Epochs his Church, headquartered at Lenburg, wove prophecy and manipulation, arranging Klein''s key to the Giant King''s Court through Edwina Edwards. His true form is a brass dragon the size of a city, a foldable tower of illusory books each bearing a brass eye. In the Apocalypse he chose self-destruction, voluntarily fusing into Grisha Adam to resist the Primordial God Almighty''s will — his residual consciousness sustaining a fragile balance at his own end.', 'white-tower', 5, null, ARRAY['God of Knowledge and Wisdom', 'Herabergen', 'Dragon of Wisdom', 'Wisdom Angel', 'Dragon of Betrayal'], ARRAY[0], ARRAY['white-tower-pathway', 'deity', 'spoiler', 'king-of-angels', 'rose-redemption', 'subsidiary-god', 'dragon', 'orthodox-gods', 'church-of-knowledge-and-wisdom'], 222)
